// PERCENTILELookback returns how many leading bars [Core.PERCENTILE] consumes
// before its first value: called with startIdx 0, its first value is at that
// bar.
//
// It takes the parameters of [Core.PERCENTILE] and returns [BadParam] for one
// out of range.
func (c *Core) PERCENTILELookback(optInTimePeriod int, optInPercentile float64) (int, error) {
	if !fitsInt32(optInTimePeriod) {
		return 0, BadParam
	}
	lookback := c.percentileLookback(int32(optInTimePeriod), optInPercentile)
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

// PERCENTILE computes the Percentile (nearest rank) over bars startIdx through
// endIdx.
//
// Rolling percentile by the nearest-rank method: sort the trailing window
// ascending and report the value whose 1-based ordinal rank is the P-th
// percentile of the window size. The result is always a value that actually
// occurred in the window, never an interpolation, so it stays on the price
// scale and never invents a level the series never traded at. At P = 50 with an
// odd window it is the rolling median; at the extremes it degenerates to the
// rolling minimum and maximum.
//
// Formula and more info at https://ta-lib.org/functions/percentile.
//
// Inputs, each at least endIdx+1 long:
//   - inReal: Source series to take the percentile of.
//
// Parameters:
//   - optInTimePeriod: Number of bars in the trailing window. Default 100;
//     range 2 to 10000; IntegerDefault selects the default.
//   - optInPercentile: Percentage position within the sorted window. Default
//     50; range 0 to 100; RealDefault selects the default.
//
// Outputs, each at least as long as the values written (the input length always
// suffices):
//   - outReal: The value at the requested rank within the trailing window.
//
// Element k of each output is the value at bar BegIdx+k of the returned
// [OutRange], and BegIdx is at least [Core.PERCENTILELookback]: a range that
// ends before it returns NBElement 0.
//
// A real output may be one of the inputs, the same slice, to compute in place;
// outputs may not otherwise share memory with an input or with each other.
//
// The error is [OutOfRangeStartIndex] or [OutOfRangeEndIndex] for a range
// outside 0 to [IndexMax] or ending before it starts, and [BadParam] for a
// parameter out of range, an input too short, an output empty or too short or
// memory shared otherwise.
func (c *Core) PERCENTILE(startIdx, endIdx int, inReal []float64, optInTimePeriod int, optInPercentile float64, outReal []float64) (OutRange, error) {
	if startIdx < 0 || startIdx > IndexMax {
		return OutRange{}, OutOfRangeStartIndex
	}
	if endIdx < 0 || endIdx > IndexMax || endIdx < startIdx {
		return OutRange{}, OutOfRangeEndIndex
	}
	if !fitsInt32(optInTimePeriod) {
		return OutRange{}, BadParam
	}
	lookback := int(c.percentileLookback(int32(optInTimePeriod), optInPercentile))
	if lookback < 0 {
		return OutRange{}, BadParam
	}
	if len(inReal) < endIdx+1 {
		return OutRange{}, BadParam
	}
	outLen := requiredOut(startIdx, endIdx, lookback)
	if len(outReal) == 0 || len(outReal) < outLen {
		return OutRange{}, BadParam
	}
	if overlapsPartly(outReal, inReal) {
		return OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	if retCode := c.percentileImpl(int32(startIdx), int32(endIdx), inReal, int32(optInTimePeriod), optInPercentile, &outBegIdx, &outNBElement, outReal); retCode != Success {
		return OutRange{}, retCode
	}
	return OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}

// PERCENTILEStream is a live PERCENTILE over a growing series:
// [PERCENTILEStream.Update] takes each new closed bar and returns the value
// [Core.PERCENTILE] computes at that bar over the same series. Open one with
