func (c *Core) percentileOpenAndFillInternal(inReal []float64, startIdx, optInTimePeriod int32, optInPercentile float64, outBegIdx, outNBElement *int32, outReal []float64) (*PERCENTILEStream, error) {
	sp := &PERCENTILEStream{core: c}
	if retCode := c.percentileOpenImpl(sp, inReal, startIdx, optInTimePeriod, optInPercentile, outBegIdx, outNBElement, outReal, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) percentileOpenInternal(inReal []float64, startIdx, optInTimePeriod int32, optInPercentile float64) (*PERCENTILEStream, error) {
	sp := &PERCENTILEStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outReal [1]float64
	if retCode := c.percentileOpenImpl(sp, inReal, startIdx, optInTimePeriod, optInPercentile, &outBegIdx, &outNBElement, sink_outReal[:], 0); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// PERCENTILEOpen opens a live [PERCENTILEStream] on a warm-up history, oldest
// bar first, and returns it with its value at the last history bar, the value
// [Core.PERCENTILE] writes there.
//
// inReal is the history; the parameters are those of [Core.PERCENTILE].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.PERCENTILELookback] bars, and [BadParam] for a parameter out of range.
func (c *Core) PERCENTILEOpen(inReal []float64, optInTimePeriod int, optInPercentile float64) (*PERCENTILEStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.percentileOpenInternal(inReal, 0, int32(optInTimePeriod), optInPercentile)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// PERCENTILEOpenAndFill opens a stream as [Core.PERCENTILEOpen] does and also
// writes the outputs over the whole history, as [Core.PERCENTILE] writes them
// for bars 0 through len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.PERCENTILELookback] values and
// share no memory with an input or another output.
//
// The errors are those of [Core.PERCENTILEOpen], and [BadParam] for an output
// that is empty, too short or sharing memory.
func (c *Core) PERCENTILEOpenAndFill(inReal []float64, optInTimePeriod int, optInPercentile float64, outReal []float64) (*PERCENTILEStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.percentileLookback(int32(optInTimePeriod), optInPercentile))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && overlaps(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.percentileOpenAndFillInternal(inReal, 0, int32(optInTimePeriod), optInPercentile, &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
